    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = [(r, c)]
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            comps.append((color, cells))

    # Find thin, right-angled line components.
    markers = []
    for color, cells in comps:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        for cr in (r0, r1):
            for cc in (c0, c1):
                arm = {(cr, c) for c in range(c0, c1 + 1)}
                arm |= {(r, cc) for r in range(r0, r1 + 1)}
                if set(cells) == arm and (r1 - r0 + 1) >= 3 and (c1 - c0 + 1) >= 3:
                    markers.append((len(arm), color, cells, cr, cc))
    if not markers:
        return [row[:] for row in grid]

    _, paint, marker_cells, cr, cc = max(markers, key=lambda x: x[0])
    mset = set(marker_cells)

    # The absent quadrant is the direction the corner points toward.
    vr = 0
    hc = 0
    if cr == min(r for r, c in marker_cells):
        vr = 1
    else:
        vr = -1
    if cc == min(c for r, c in marker_cells):
        hc = 1
    else:
        hc = -1

    def is_line(cells):
        if len(cells) < 3:
            return False
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        return min(rs) == max(rs) or min(cs) == max(cs)

    def dist_in_sector(cells):
        best = None
        for r, c in cells:
            # Permit a one-cell tolerance across the quadrant boundary.
            if vr * (r - cr) >= 0 and hc * (c - cc) >= -1:
                d = (r - cr) ** 2 + (c - cc) ** 2
                if best is None or d < best:
                    best = d
        return best

    candidates = []
    for color, cells in comps:
        if set(cells) == mset or is_line(cells):
            continue
        d = dist_in_sector(cells)
        if d is not None:
            candidates.append((d, color, cells))

    if not candidates:
        for color, cells in comps:
            if set(cells) != mset and not is_line(cells):
                d = min((r - cr) ** 2 + (c - cc) ** 2 for r, c in cells)
                candidates.append((d, color, cells))

    out = [row[:] for row in grid]
    if candidates:
        _, _, target = min(candidates, key=lambda x: x[0])
        for r, c in target:
            out[r][c] = paint
    return out
